CREATE TABLE Alergenos ( ID_Alergeno TEXT NOT NULL PRIMARY KEY, Nombre TEXT NOT NULL UNIQUE, Nombre_Imagen TEXT, Ruta_Imagen TEXT );
CREATE TABLE Aperturas_Cajon ( ID_Apertura TEXT NOT NULL PRIMARY KEY, ID_Usuario TEXT, Fecha DATETIME NOT NULL, FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) ON DELETE SET NULL );
CREATE TABLE Applied_Operations ( ID_Applied_Operation INTEGER PRIMARY KEY AUTOINCREMENT, Op_Id TEXT NOT NULL, Command_Name TEXT NOT NULL, Request_Hash TEXT NOT NULL, Device_Id TEXT, Status TEXT NOT NULL DEFAULT 'PROCESSING', Result_Json TEXT, Error_Text TEXT, Created_At_Ms INTEGER NOT NULL, Applied_At_Ms INTEGER, Updated_At_Ms INTEGER NOT NULL, UNIQUE (Op_Id), CHECK (Status IN ('PROCESSING', 'APPLIED', 'FAILED')) );
CREATE TABLE Asignacion_Turnos ( ID_Asignacion TEXT NOT NULL PRIMARY KEY, ID_Trabajador TEXT NOT NULL, Fecha DATE NOT NULL, ID_Turno TEXT NOT NULL, Area TEXT NOT NULL, Hora_Inicio TIME, Hora_Fin TIME, Notas TEXT, ID_Grupo TEXT, FOREIGN KEY (ID_Trabajador) REFERENCES Trabajadores(ID_Trabajador), FOREIGN KEY (ID_Turno) REFERENCES Turnos(ID_Turno) );
CREATE TABLE Business_Settings ( ID INTEGER PRIMARY KEY CHECK (ID = 1), Business_Name TEXT NOT NULL DEFAULT 'TPV', Logo_DataUrl TEXT, Direccion TEXT DEFAULT '', Telefono TEXT DEFAULT '', CIF TEXT DEFAULT '', Mensaje_Footer TEXT DEFAULT '¡Gracias por su visita!', IVA_Percent REAL NOT NULL DEFAULT 10, -- A partir de cuanto descuadre el cierre de caja exige escribir un motivo (CUENTA-06). 5 euros -- deja pasar el centimo de redondeo y el error de vuelta sin dar la lata, y obliga a explicar lo -- que ya es dinero de verdad. Cada negocio lo ajusta. Umbral_Descuadre INTEGER NOT NULL DEFAULT 500 CHECK (typeof(Umbral_Descuadre) IN ('integer','null')), -- ── FISCAL-01 (Veri*factu) ────────────────────────────────────────────────────────────────── -- Razon_Social NO es Business_Name. "Bar La Plaza" es el rotulo; "Francisco Garcia SL" es quien -- factura. El ticket ensena los dos; el registro de facturacion (NombreRazonEmisor y el bloque -- ObligadoEmision de la cabecera) solo el segundo. Razon_Social TEXT NOT NULL DEFAULT '', -- DescripcionOperacion es un campo OBLIGATORIO del registro (hasta 500 caracteres). No se deriva -- de las lineas: los nombres de producto los escribe el usuario y un campo obligatorio que puede -- llegar vacio o con basura es un rechazo garantizado. Texto fijo, configurable. Descripcion_Op TEXT NOT NULL DEFAULT 'Servicios de hosteleria y restauracion', -- Limite (IVA incluido) por encima del cual una factura simplificada (F2) ya no vale y hay que -- emitir factura completa (F1). El general del art. 4.1 RD 1619/2012 son 400 EUR, pero la -- hosteleria esta en la lista del art. 4.2 y sube a 3.000. La AEAT lo valida en el servicio web -- (error 1150). Va aqui y no incrustado porque es un numero que la norma puede mover. Limite_Simplif INTEGER NOT NULL DEFAULT 300000 CHECK (typeof(Limite_Simplif) IN ('integer','null')), -- 'produccion' | 'pruebas'. Cambia A LA VEZ el endpoint del servicio web y la URL del QR que se -- imprime en el papel. Un ticket emitido en pruebas lleva un QR que apunta a prewww2.aeat.es: la -- pantalla tiene que gritarlo. Es una decision explicita y visible, y no una variable de entorno, -- porque produccion y pruebas se distinguen en tres caracteres (www1 / prewww1). Verifactu_Entorno TEXT NOT NULL DEFAULT 'produccion', -- MODO-PRUEBA (temporal): con 1, los cobros numeran en la serie PRUEBA y NO emiten registro de -- facturacion: sin QR, sin envio a la AEAT y sin necesitar NIF ni certificado. Sirve para probar -- el programa mientras Veri*factu no es obligatorio, y se quita entero antes de que lo sea (la -- fecha, en docs/pendientes.md, VF-MODO-PRUEBA): un interruptor que deja de declarar ventas no -- puede existir en un TPV que se venda. Modo_Prueba INTEGER NOT NULL DEFAULT 0, -- RI-61: lo que dura una reserva que no elige su duracion (minutos), y que pasa cuando dos -- reservas de la misma mesa se pisan: 'avisar' (se guarda si quien reserva lo confirma) o -- 'prohibir'. Una comanda abierta en la mesa cuenta como ocupada desde que se abrio. Reserva_Duracion_Min INTEGER NOT NULL DEFAULT 120 CHECK (Reserva_Duracion_Min > 0), Reserva_Solape TEXT NOT NULL DEFAULT 'avisar', -- Reservas desde la web (docs/estudios/reservas-web.md). Reserva_Web_Activa es el interruptor -- general. Dias_Min / Dias_Max: desde cuantos dias vista y hasta cuantos se puede reservar (1 = -- desde manana: hoy ya no se reserva para hoy). Margen_Min: la tolerancia, en minutos, de la -- franja de una mesa por cada extremo. Margen_Plazas: para N personas se ofrecen mesas de N a -- N + Margen_Plazas plazas. De momento solo el interruptor tiene pantalla; el resto son ajustes -- con su valor por defecto, para que hacerlos configurables no necesite otra migracion. Reserva_Web_Activa INTEGER NOT NULL DEFAULT 0, Reserva_Web_Dias_Min INTEGER NOT NULL DEFAULT 1, Reserva_Web_Dias_Max INTEGER NOT NULL DEFAULT 30, Reserva_Web_Margen_Min INTEGER NOT NULL DEFAULT 20, Reserva_Web_Margen_Plazas INTEGER NOT NULL DEFAULT 2, -- Zona horaria IANA del negocio ('Europe/Madrid', 'Atlantic/Canary'…). La escribe la Main con la -- de su sistema: la nube la necesita para saber que es «hoy» cuando no hay un dispositivo que se -- lo diga (las reservas desde la web). Zona_Horaria TEXT NOT NULL DEFAULT 'Europe/Madrid', Updated_At TEXT, -- A los cuantos minutos de su hora se marca "No vino" (NO_SHOW) una reserva a la que no ha -- llegado nadie (sigue PROXIMA). 0 = nunca: se queda por llegar hasta que alguien la cierre o la -- cancele. Lo aplica el job reservas_no_vino de la Main; se cambia en Configuracion -> Reservas. Reserva_No_Vino_Min INTEGER NOT NULL DEFAULT 0 CHECK (Reserva_No_Vino_Min >= 0 AND Reserva_No_Vino_Min <= 1440), CHECK (Verifactu_Entorno IN ('produccion','pruebas')), CHECK (Reserva_Solape IN ('avisar','prohibir')), CHECK (Reserva_Web_Activa IN (0, 1)), CHECK (Reserva_Web_Dias_Min >= 0 AND Reserva_Web_Dias_Max >= Reserva_Web_Dias_Min), CHECK (Reserva_Web_Margen_Min >= 0 AND Reserva_Web_Margen_Plazas >= 0) );
CREATE TABLE Categorias_Producto ( ID_Categoria TEXT NOT NULL PRIMARY KEY, Nombre TEXT NOT NULL UNIQUE, Nombre_Imagen TEXT, Ruta_Imagen TEXT, Vendible INTEGER NOT NULL DEFAULT 1, Pasa_Cocina INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE Cierre_Denominaciones ( ID_Cierre TEXT NOT NULL, Momento TEXT NOT NULL, Valor INTEGER NOT NULL CHECK (typeof(Valor) IN ('integer','null')), Unidades INTEGER NOT NULL, PRIMARY KEY (ID_Cierre, Momento, Valor), CHECK (Momento IN ('CONTADO','DEJADO')), FOREIGN KEY (ID_Cierre) REFERENCES Cierres_Caja(ID_Cierre) ON DELETE CASCADE );
CREATE TABLE Cierre_Rectificaciones ( ID_Rectificacion TEXT NOT NULL PRIMARY KEY, ID_Cierre TEXT NOT NULL, Fecha_Hora DATETIME NOT NULL, ID_Usuario TEXT, Descripcion TEXT NOT NULL, Motivo TEXT, Esperado_Antes INTEGER NOT NULL CHECK (typeof(Esperado_Antes) IN ('integer','null')), Esperado_Despues INTEGER NOT NULL CHECK (typeof(Esperado_Despues) IN ('integer','null')), Descuadre_Antes INTEGER NOT NULL CHECK (typeof(Descuadre_Antes) IN ('integer','null')), Descuadre_Despues INTEGER NOT NULL CHECK (typeof(Descuadre_Despues) IN ('integer','null')), FOREIGN KEY (ID_Cierre) REFERENCES Cierres_Caja(ID_Cierre) ON DELETE CASCADE, FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) ON DELETE SET NULL );
CREATE TABLE Cierres_Caja ( ID_Cierre TEXT NOT NULL PRIMARY KEY, Fecha_Hora DATETIME NOT NULL, ID_Usuario TEXT, Fondo_Inicial INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Fondo_Inicial) IN ('integer','null')), Ventas_Efectivo INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Ventas_Efectivo) IN ('integer','null')), Esperado INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Esperado) IN ('integer','null')), Contado INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Contado) IN ('integer','null')), Descuadre INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Descuadre) IN ('integer','null')), Dejado INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Dejado) IN ('integer','null')), Retirado INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Retirado) IN ('integer','null')), Motivo TEXT, Reabierto_En DATETIME, Reabierto_Por TEXT, -- Desde cuando cuenta (exclusivo): la Fecha_Hora del cierre anterior; NULL en el primero. Es lo -- que dice a que cierre pertenece un apunte que se corrige despues. Periodo_Desde DATETIME, -- Gastos pagados con dinero del cajon durante el periodo. Restan del esperado. Gastos_Caja INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Gastos_Caja) IN ('integer','null')), -- Lo que el cierre marca HOY tras corregir apuntes de su periodo. NULL = nunca se ha rectificado. Rect_Ventas_Efectivo INTEGER CHECK (typeof(Rect_Ventas_Efectivo) IN ('integer','null')), Rect_Gastos_Caja INTEGER CHECK (typeof(Rect_Gastos_Caja) IN ('integer','null')), Rect_Esperado INTEGER CHECK (typeof(Rect_Esperado) IN ('integer','null')), Rect_Descuadre INTEGER CHECK (typeof(Rect_Descuadre) IN ('integer','null')), FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) ON DELETE SET NULL, FOREIGN KEY (Reabierto_Por) REFERENCES Usuarios(ID_Usuario) ON DELETE SET NULL );
CREATE TABLE Clientes ( ID_Cliente TEXT NOT NULL PRIMARY KEY, Nombre TEXT NOT NULL, Telefono TEXT, Email TEXT, Notas TEXT, Total_Gastado INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Total_Gastado) IN ('integer','null')), Created_At TEXT, -- FISCAL-02: datos para emitir una factura COMPLETA (F1/F3) a este cliente. Son opcionales: la -- inmensa mayoria de los clientes de un bar no piden factura y nunca los tendran. -- NIF + Razon_Social -> van al REGISTRO de facturacion (bloque Destinatarios). -- Direccion_Fiscal -> solo al PAPEL (art. 6 ROF exige el domicilio del destinatario en la -- factura, pero el registro de la AEAT no lo lleva). -- Existen para que la comida de empresa que se repite cada mes no dicte el NIF doce veces. NIF TEXT, Razon_Social TEXT, Direccion_Fiscal TEXT );
CREATE TABLE Comandas ( ID_Comanda TEXT NOT NULL PRIMARY KEY, ID_Mesa TEXT NULL, ID_Reserva TEXT NULL, ID_Cliente TEXT NULL, ID_Trabajador TEXT NULL, Canal TEXT NOT NULL DEFAULT 'MESA', Fecha_Hora_Apertura TEXT NOT NULL, Fecha_Hora_Cierre TEXT NULL, Total_Comanda INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Total_Comanda) IN ('integer','null')), Estado TEXT NOT NULL DEFAULT 'Abierta', FOREIGN KEY (ID_Mesa) REFERENCES Mesas(ID_Mesa), FOREIGN KEY (ID_Reserva) REFERENCES Reservas(ID_Reserva), FOREIGN KEY (ID_Cliente) REFERENCES Clientes(ID_Cliente), FOREIGN KEY (ID_Trabajador) REFERENCES Trabajadores(ID_Trabajador) ON DELETE SET NULL, CHECK (Canal IN ('MESA', 'BARRA')), CHECK (Estado IN ('Abierta', 'Pagada')), CHECK ((Canal = 'MESA') = (ID_Mesa IS NOT NULL)) );
CREATE TABLE Contact_Settings ( ID INTEGER PRIMARY KEY CHECK (ID = 1), Contact_Email TEXT NOT NULL DEFAULT '', Contact_Phone TEXT NOT NULL DEFAULT '', Updated_At TEXT );
CREATE TABLE Cuentas_Gastos ( ID_Gasto TEXT NOT NULL PRIMARY KEY, Fecha DATE NOT NULL, Concepto TEXT NOT NULL, Importe INTEGER NOT NULL CHECK (typeof(Importe) IN ('integer','null')), Tipo_Gasto TEXT NOT NULL, ID_Proveedor TEXT NULL, Pagado_Con_Caja INTEGER NOT NULL DEFAULT 0, CHECK (Pagado_Con_Caja IN (0, 1)), FOREIGN KEY (ID_Proveedor) REFERENCES Proveedores(ID_Proveedor) ON DELETE SET NULL );
CREATE TABLE Detalle_Comanda ( ID_Detalle TEXT NOT NULL PRIMARY KEY, ID_Comanda TEXT NOT NULL, ID_Producto TEXT, Nombre_Producto TEXT, Cantidad REAL NOT NULL, Precio_Unitario INTEGER NOT NULL CHECK (typeof(Precio_Unitario) IN ('integer','null')), IVA_Percent REAL, Notas TEXT, Estado_Cocina TEXT DEFAULT 'PENDIENTE', Fecha_Hora_Cocina DATETIME, ID_Usuario_Cocinero TEXT, FOREIGN KEY (ID_Comanda) REFERENCES Comandas(ID_Comanda), FOREIGN KEY (ID_Producto) REFERENCES Productos(ID_Producto) ON DELETE SET NULL );
CREATE TABLE Devolucion_Lineas ( ID_Pago TEXT NOT NULL, ID_Detalle TEXT NOT NULL, Cantidad REAL NOT NULL, Importe INTEGER NOT NULL CHECK (typeof(Importe) IN ('integer','null')), PRIMARY KEY (ID_Pago, ID_Detalle), FOREIGN KEY (ID_Pago) REFERENCES Pagos(ID_Pago) ON DELETE CASCADE, FOREIGN KEY (ID_Detalle) REFERENCES Detalle_Comanda(ID_Detalle) ON DELETE CASCADE, CHECK (Cantidad > 0), CHECK (Importe >= 0) );
CREATE TABLE Fichaje_Dia ( ID_Usuario TEXT NOT NULL, Fecha DATE NOT NULL, Turno_Partido INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (ID_Usuario, Fecha), FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) );
CREATE TABLE Fichajes ( ID_Fichaje TEXT NOT NULL PRIMARY KEY, ID_Usuario TEXT NOT NULL, Fecha DATE NOT NULL, Parte INTEGER NOT NULL DEFAULT 1, Hora_Entrada DATETIME, Hora_Salida DATETIME, Estado TEXT DEFAULT 'ABIERTO', Cerrado_Automatico INTEGER DEFAULT 0, Cierre_Motivo TEXT, Incidencia TEXT, UNIQUE(ID_Usuario, Fecha, Parte), FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) );
CREATE TABLE Horario_Predeterminado ( ID_Default TEXT NOT NULL PRIMARY KEY, ID_Trabajador TEXT NOT NULL, Weekday INTEGER NOT NULL, Orden INTEGER NOT NULL DEFAULT 1, ID_Turno TEXT NOT NULL, Area TEXT NOT NULL, Hora_Inicio TIME, Hora_Fin TIME, Notas TEXT, FOREIGN KEY (ID_Trabajador) REFERENCES Trabajadores(ID_Trabajador) ON DELETE CASCADE, FOREIGN KEY (ID_Turno) REFERENCES Turnos(ID_Turno), UNIQUE (ID_Trabajador, Weekday, Orden) );
CREATE TABLE Intentos_Login ( ID_Usuario TEXT NOT NULL PRIMARY KEY, Intentos_Fallidos INTEGER NOT NULL DEFAULT 0, Bloqueado_Hasta_Ms INTEGER NOT NULL DEFAULT 0, Ultimo_Intento_Ms INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) ON DELETE CASCADE );
CREATE TABLE Lineas_Pedido_Proveedor ( ID_Linea TEXT NOT NULL PRIMARY KEY, ID_Pedido TEXT NOT NULL, Nombre_Producto TEXT NOT NULL, Cantidad REAL NOT NULL DEFAULT 1, Precio_Unitario INTEGER CHECK (typeof(Precio_Unitario) IN ('integer','null')), Unidad TEXT, FOREIGN KEY (ID_Pedido) REFERENCES Pedidos_Proveedor(ID_Pedido) ON DELETE CASCADE );
CREATE TABLE Lote_Consumos ( ID_Detalle TEXT NOT NULL, ID_Lote TEXT NOT NULL, -- STOCK-01: el COBRO que hizo este consumo. Una linea cobrada, anulada y vuelta a cobrar deja un -- consumo por cobro, y de lotes distintos si el primero se agoto entre medias. Sin saber de que -- cobro es cada uno, anular el segundo devolvia tambien lo del primero, que ya habia vuelto a su -- lote: stock fantasma. Anular devuelve SOLO lo de su cobro. Se inserta DESPUES del pago: la FK -- se comprueba sentencia a sentencia, tambien al replicarla en la nube. ID_Pago TEXT NOT NULL, Cantidad REAL NOT NULL, PRIMARY KEY (ID_Detalle, ID_Lote, ID_Pago), FOREIGN KEY (ID_Detalle) REFERENCES Detalle_Comanda(ID_Detalle) ON DELETE CASCADE, FOREIGN KEY (ID_Lote) REFERENCES Lotes_Producto(ID_Lote), FOREIGN KEY (ID_Pago) REFERENCES Pagos(ID_Pago) ON DELETE CASCADE, CHECK (Cantidad > 0) );
CREATE TABLE Lotes_Producto ( ID_Lote TEXT NOT NULL PRIMARY KEY, ID_Producto TEXT NOT NULL, Codigo_Lote TEXT NOT NULL, Fecha_Entrada DATETIME NOT NULL, Caducidad DATE, Stock_Disponible REAL NOT NULL DEFAULT 0, Coste_Unitario INTEGER CHECK (typeof(Coste_Unitario) IN ('integer','null')), ID_Proveedor TEXT, Notas TEXT, FOREIGN KEY (ID_Producto) REFERENCES Productos(ID_Producto) ON DELETE CASCADE, FOREIGN KEY (ID_Proveedor) REFERENCES Proveedores(ID_Proveedor), UNIQUE (ID_Producto, Codigo_Lote) );
CREATE TABLE Mesas ( ID_Mesa TEXT NOT NULL PRIMARY KEY, ID_Zona TEXT NOT NULL, Numero_Mesa TEXT NOT NULL, Capacidad INTEGER NOT NULL, Ubicacion_X INTEGER NOT NULL, Ubicacion_Y INTEGER NOT NULL, Shape TEXT NOT NULL, Width INTEGER NOT NULL, Height INTEGER NOT NULL, Radius INTEGER, Updated_At DATETIME, Archivada_En DATETIME, FOREIGN KEY (ID_Zona) REFERENCES Zonas(ID_Zona) ON DELETE CASCADE );
CREATE TABLE Movimientos_Caja ( ID_Movimiento TEXT NOT NULL PRIMARY KEY, Fecha_Hora TEXT NOT NULL, Tipo TEXT NOT NULL, ID_Pago TEXT, ID_Gasto TEXT, ID_Usuario TEXT, ID_Trabajador TEXT, Importe INTEGER NOT NULL DEFAULT 0 CHECK (typeof(Importe) IN ('integer','null')), Metodo_Pago TEXT, Motivo TEXT, FOREIGN KEY (ID_Pago) REFERENCES Pagos(ID_Pago) ON DELETE SET NULL, FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) ON DELETE SET NULL, FOREIGN KEY (ID_Trabajador) REFERENCES Trabajadores(ID_Trabajador) ON DELETE SET NULL, CHECK (Tipo IN ('COBRO','ANULACION','DEVOLUCION','GASTO','GASTO_ANULADO')) );
CREATE TABLE Movimientos_Stock ( ID_Movimiento TEXT NOT NULL PRIMARY KEY, ID_Lote TEXT, ID_Producto TEXT, Tipo TEXT NOT NULL, Delta REAL NOT NULL, Stock_Resultante REAL NOT NULL, Motivo TEXT, ID_Usuario TEXT, Fecha DATETIME NOT NULL, FOREIGN KEY (ID_Lote) REFERENCES Lotes_Producto(ID_Lote) ON DELETE CASCADE, FOREIGN KEY (ID_Producto) REFERENCES Productos(ID_Producto) ON DELETE CASCADE, FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) ON DELETE SET NULL, CHECK (Tipo IN ('ALTA', 'AJUSTE')), CHECK ((ID_Lote IS NULL) <> (ID_Producto IS NULL)) );
CREATE TABLE Notificacion_Lecturas ( ID_Notificacion TEXT NOT NULL, ID_Usuario TEXT NOT NULL, Leida_En DATETIME NOT NULL, PRIMARY KEY (ID_Notificacion, ID_Usuario), FOREIGN KEY (ID_Notificacion) REFERENCES Notificaciones(ID_Notificacion) ON DELETE CASCADE );
CREATE TABLE Notificaciones ( ID_Notificacion TEXT NOT NULL PRIMARY KEY, Tipo TEXT NOT NULL, Severidad TEXT NOT NULL DEFAULT 'info', Titulo TEXT NOT NULL, Cuerpo TEXT, Destino_Tipo TEXT NOT NULL, Destino_Valor TEXT, Accion TEXT, Payload TEXT, Clave_Dedupe TEXT, Estado TEXT NOT NULL DEFAULT 'activa', Creada_En DATETIME NOT NULL, Expira_En DATETIME, CHECK (Destino_Tipo IN ('todos', 'usuario', 'rol')), CHECK (Severidad IN ('info', 'exito', 'aviso', 'error')), CHECK (Estado IN ('activa', 'resuelta', 'descartada')) );
CREATE TABLE Pago_Detalles ( ID_Pago TEXT NOT NULL, ID_Detalle TEXT NOT NULL, PRIMARY KEY (ID_Pago, ID_Detalle), FOREIGN KEY (ID_Pago) REFERENCES Pagos(ID_Pago), FOREIGN KEY (ID_Detalle) REFERENCES Detalle_Comanda(ID_Detalle) ON DELETE CASCADE );
CREATE TABLE Pagos ( ID_Pago TEXT NOT NULL PRIMARY KEY, ID_Comanda TEXT NOT NULL, Fecha_Hora DATETIME NOT NULL, Metodo_Pago TEXT NOT NULL, Importe_Total INTEGER NOT NULL CHECK (typeof(Importe_Total) IN ('integer','null')), Tipo TEXT NOT NULL, ID_Usuario_Cobrador TEXT, ID_Trabajador_Cobrador TEXT, Numero_Ticket TEXT, Estado TEXT NOT NULL DEFAULT 'ACTIVO', Anulado_En TEXT, Anulado_Por TEXT, Motivo_Anulacion TEXT, -- FISCAL-01: POR QUE este cobro dejo de contar. Son dos instrumentos legales distintos y el -- registro de facturacion que genera cada uno es distinto: -- -- 'ERROR' -> la venta NO EXISTIO (ticket de prueba, mesa equivocada). Genera un -- RF DE ANULACION (art. 11.1 RRSIF). La AEAT dice en su FAQ que estos casos -- deben ser "MUY POCO FRECUENTES". Las lineas vuelven a la comanda. -- 'DEVOLUCION' -> la venta SI EXISTIO y se devuelve el dinero. Genera una FACTURA -- RECTIFICATIVA (RF de alta R5, TipoRectificativa=I, importe negativo). La -- AEAT es explicita: "todas las facturas emitidas, en la medida en que -- respondan a operaciones realmente efectuadas (como es el caso habitual) NO -- PUEDEN ANULARSE". Las lineas NO vuelven: se vendieron. -- -- Antes las dos cosas salian por el mismo boton, y la que mas se va a usar -la devolucion- es -- justo la que no era una anulacion. -- -- NO se toca `Estado` para distinguirlas, y eso es la decision: en este esquema 'ANULADO' ya -- significa "no cuenta como venta", y las dos lo son. Mezclar el motivo en `Estado` obligaria a -- revisar las ~14 consultas que filtran por el -el arqueo, las estadisticas, el pendiente de una -- comanda, la reconciliacion y sus espejos del worker- para algo que al cajon le da igual: el -- dinero salio en los dos casos. Lo que cambia es el papel que hay que emitir. Motivo_Baja TEXT, -- La DEVOLUCION de parte de un cobro: el cliente devuelve unas lineas, o unas unidades de una -- linea, y se le devuelve su dinero. Es un pago NEGATIVO de la misma comanda que apunta al cobro -- devuelto (ID_Pago_Origen), con Tipo = 'DEVOLUCION', el metodo por el que salio el dinero -- ('Efectivo', 'Tarjeta' u 'Otro') y por que (Motivo_Devolucion). Lo devuelto de cada linea esta -- en Devolucion_Lineas. -- -- Va como un pago y no como una baja porque es dinero que sale: el arqueo, los resumenes y las -- estadisticas lo restan sin saber que existe, y sale en su periodo de caja, que es el dia que -- el dinero se fue. El cobro devuelto sigue ACTIVO: se vendio. La devolucion de un cobro -- ENTERO es otra cosa (Motivo_Baja = 'DEVOLUCION'), y no cabe en uno que ya tenga parciales. ID_Pago_Origen TEXT, Motivo_Devolucion TEXT, FOREIGN KEY (ID_Comanda) REFERENCES Comandas(ID_Comanda) ON DELETE CASCADE, FOREIGN KEY (ID_Usuario_Cobrador) REFERENCES Usuarios(ID_Usuario) ON DELETE SET NULL, FOREIGN KEY (ID_Trabajador_Cobrador) REFERENCES Trabajadores(ID_Trabajador) ON DELETE SET NULL, FOREIGN KEY (Anulado_Por) REFERENCES Usuarios(ID_Usuario) ON DELETE SET NULL, FOREIGN KEY (ID_Pago_Origen) REFERENCES Pagos(ID_Pago), CHECK (Estado IN ('ACTIVO','ANULADO')), CHECK ((Estado = 'ANULADO') = (Anulado_En IS NOT NULL AND Anulado_Por IS NOT NULL)), CHECK (Motivo_Baja IS NULL OR Motivo_Baja IN ('ERROR','DEVOLUCION')), CHECK ((Motivo_Baja IS NOT NULL) <= (Estado = 'ANULADO')), CHECK ((ID_Pago_Origen IS NULL) = (Motivo_Devolucion IS NULL)), CHECK (ID_Pago_Origen IS NULL OR (Importe_Total < 0 AND Tipo = 'DEVOLUCION')) );
CREATE TABLE Pedidos_Proveedor ( ID_Pedido TEXT NOT NULL PRIMARY KEY, ID_Proveedor TEXT, Email_Destino TEXT, Estado TEXT NOT NULL DEFAULT 'borrador', Fecha_Creacion TEXT NOT NULL, Fecha_Envio TEXT, Notas TEXT, FOREIGN KEY (ID_Proveedor) REFERENCES Proveedores(ID_Proveedor) ON DELETE SET NULL, CHECK (Estado IN ('borrador', 'enviado', 'cancelado')) );
CREATE TABLE Producto_Alergenos ( ID_Producto TEXT NOT NULL, ID_Alergeno TEXT NOT NULL, PRIMARY KEY (ID_Producto, ID_Alergeno), FOREIGN KEY (ID_Producto) REFERENCES Productos(ID_Producto) ON DELETE CASCADE, FOREIGN KEY (ID_Alergeno) REFERENCES Alergenos(ID_Alergeno) ON DELETE CASCADE );
CREATE TABLE Productos ( ID_Producto TEXT NOT NULL PRIMARY KEY, ID_Categoria TEXT NOT NULL, ID_Proveedor TEXT, Nombre TEXT NOT NULL, Precio_Venta INTEGER CHECK (typeof(Precio_Venta) IN ('integer','null')), Stock_Minimo REAL DEFAULT 0, Unidad_Medida TEXT, Nombre_Imagen TEXT, Ruta_Imagen TEXT, Cantidad_Pedido_Esperada REAL, -- VR-04: stock "suelto" fuera de lotes. Contador simple por producto, OPCIONAL (NULL = el producto -- no usa stock suelto y se vende sin descontar de aqui). Un cobro nunca toma de un lote mas de lo -- que tiene y lo que los lotes no cubren se descuenta de aqui, asi que es este contador el que -- queda negativo: la senal honesta de sobreventa. Un lote solo baja de 0 si dos cobros a la vez lo -- consumen y se replican (VR-06). El stock total mostrado de un producto es -- SUM(lotes) + COALESCE(Stock_Suelto, 0). Stock_Suelto REAL, -- Tipo de IVA propio del producto. NULL = "hereda el del negocio" -- (Business_Settings.IVA_Percent), que es el caso de casi todo: en hosteleria el consumo en el -- establecimiento va al tipo reducido, bebida incluida. Deja de valer en cuanto se vende algo -- para llevar envasado, tabaco o merchandising, que tributan a otro tipo. -- Es nullable a proposito y no DEFAULT 10: "no decidido" y "decidido que sea 10" son cosas -- distintas. Un producto que nadie ha tocado tiene que SEGUIR al tipo general si este cambia; -- un 10 escrito en la fila se quedaria congelado sin que nadie lo pidiera. IVA_Percent REAL, Archivado_En DATETIME, FOREIGN KEY (ID_Categoria) REFERENCES Categorias_Producto(ID_Categoria), FOREIGN KEY (ID_Proveedor) REFERENCES Proveedores(ID_Proveedor) );
CREATE TABLE Proveedores ( ID_Proveedor TEXT NOT NULL PRIMARY KEY, Nombre_Empresa TEXT NOT NULL, Contacto TEXT, Telefono TEXT, Email TEXT UNIQUE, CIF TEXT UNIQUE, Informacion_adicional TEXT, Nombre_Imagen TEXT, Ruta_Imagen TEXT );
CREATE TABLE Registros_Facturacion ( ID_Registro TEXT NOT NULL PRIMARY KEY, Orden INTEGER NOT NULL, Tipo TEXT NOT NULL, NIF_Emisor TEXT NOT NULL, Num_Serie_Factura TEXT NOT NULL, Fecha_Expedicion TEXT NOT NULL, Fecha_Operacion TEXT, Serie TEXT NOT NULL, Numero INTEGER NOT NULL, Nombre_Razon_Emisor TEXT NOT NULL, Tipo_Factura TEXT, Tipo_Rectificativa TEXT, Descripcion_Operacion TEXT, Importe_Total TEXT, Cuota_Total TEXT, Desglose_Json TEXT, Destinatario_Json TEXT, Referencias_Json TEXT, Macrodato TEXT, Primer_Registro TEXT, Ant_NIF TEXT, Ant_Num_Serie TEXT, Ant_Fecha TEXT, Ant_Huella TEXT, Cadena_Huella TEXT NOT NULL, Huella TEXT NOT NULL, Tipo_Huella TEXT NOT NULL DEFAULT '01', Fecha_Hora_Huso TEXT NOT NULL, Subsanacion TEXT, Rechazo_Previo TEXT, Sin_Registro_Previo TEXT, Subsana_ID_Registro TEXT, Sistema_Json TEXT NOT NULL, QR_Url TEXT NOT NULL, Incidencia TEXT NOT NULL DEFAULT 'N', ID_Pago TEXT, UNIQUE (Orden), FOREIGN KEY (ID_Pago) REFERENCES Pagos(ID_Pago) ON DELETE SET NULL, CHECK (Tipo IN ('ALTA','ANULACION')), CHECK (Tipo_Factura IS NULL OR Tipo_Factura IN ('F1','F2','F3','R1','R2','R3','R4','R5')), CHECK (Tipo_Rectificativa IS NULL OR Tipo_Rectificativa IN ('S','I')), CHECK (Primer_Registro IS NULL OR Primer_Registro = 'S'), CHECK (Subsanacion IS NULL OR Subsanacion IN ('S','N')), CHECK (Rechazo_Previo IS NULL OR Rechazo_Previo IN ('N','S','X')), CHECK (Sin_Registro_Previo IS NULL OR Sin_Registro_Previo IN ('N','S')), CHECK (Macrodato IS NULL OR Macrodato IN ('N','S')), CHECK (Incidencia IN ('N','S')), CHECK (Tipo_Huella = '01') );
CREATE TABLE Reserva_Web_Cierres ( ID_Cierre TEXT NOT NULL PRIMARY KEY, Dia_YMD TEXT NOT NULL UNIQUE, Motivo TEXT );
CREATE TABLE Reserva_Web_Franjas ( ID_Franja TEXT NOT NULL PRIMARY KEY, ID_Mesa TEXT NOT NULL, Dias_Semana INTEGER NOT NULL DEFAULT 127, Fecha_Desde TEXT, Fecha_Hasta TEXT, Hora_Desde TEXT NOT NULL, Hora_Hasta TEXT NOT NULL, CHECK (Dias_Semana BETWEEN 1 AND 127), CHECK (Hora_Desde < Hora_Hasta), CHECK (Fecha_Desde IS NULL OR Fecha_Hasta IS NULL OR Fecha_Desde <= Fecha_Hasta), FOREIGN KEY (ID_Mesa) REFERENCES Mesas(ID_Mesa) ON DELETE CASCADE );
CREATE TABLE Reserva_Web_Mesas ( ID_Mesa TEXT NOT NULL PRIMARY KEY, Activa INTEGER NOT NULL DEFAULT 0, CHECK (Activa IN (0, 1)), FOREIGN KEY (ID_Mesa) REFERENCES Mesas(ID_Mesa) ON DELETE CASCADE );
CREATE TABLE Reservas ( ID_Reserva TEXT NOT NULL PRIMARY KEY, ID_Cliente TEXT, ID_Mesa TEXT, Dia_YMD TEXT NOT NULL, Hora TEXT NOT NULL, Turno TEXT NOT NULL, Comensales INTEGER NOT NULL DEFAULT 1, Duracion_Min INTEGER CHECK (Duracion_Min IS NULL OR Duracion_Min > 0), Nota TEXT, -- RES-05: una reserva nace por llegar. ACTIVA es el cliente ya sentado. Estado TEXT NOT NULL DEFAULT 'PROXIMA', Created_At TEXT, Origen TEXT NOT NULL DEFAULT 'TPV', FOREIGN KEY (ID_Cliente) REFERENCES Clientes(ID_Cliente), FOREIGN KEY (ID_Mesa) REFERENCES Mesas(ID_Mesa) );
CREATE TABLE Roles ( ID_Rol TEXT NOT NULL PRIMARY KEY, Nombre_Rol TEXT NOT NULL UNIQUE );
CREATE TABLE Roles_Permisos ( ID_Rol_Permiso TEXT NOT NULL PRIMARY KEY, ID_Rol TEXT NOT NULL REFERENCES Roles(ID_Rol), Permiso TEXT NOT NULL, UNIQUE (ID_Rol, Permiso) );
CREATE TABLE Serie_Facturacion ( Serie TEXT NOT NULL PRIMARY KEY, Ultimo INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE Suelto_Consumos ( ID_Detalle TEXT NOT NULL, ID_Producto TEXT NOT NULL, -- STOCK-01: el cobro que hizo este consumo, por lo mismo que en Lote_Consumos. ID_Pago TEXT NOT NULL, Cantidad REAL NOT NULL, PRIMARY KEY (ID_Detalle, ID_Producto, ID_Pago), FOREIGN KEY (ID_Detalle) REFERENCES Detalle_Comanda(ID_Detalle) ON DELETE CASCADE, FOREIGN KEY (ID_Pago) REFERENCES Pagos(ID_Pago) ON DELETE CASCADE, CHECK (Cantidad > 0) );
CREATE TABLE Sync_Changes ( Seq INTEGER PRIMARY KEY AUTOINCREMENT, Op_Id TEXT NOT NULL, Command_Name TEXT, Statements_Json TEXT NOT NULL, Device_Id TEXT, Created_At_Ms INTEGER NOT NULL );
CREATE TABLE Sync_Main_Checkpoints ( Device_Id TEXT NOT NULL PRIMARY KEY, Last_Seq INTEGER NOT NULL, Updated_At_Ms INTEGER NOT NULL );
CREATE TABLE Tarea_Asignaciones ( ID_Tarea TEXT NOT NULL, ID_Trabajador TEXT NOT NULL, Asignada_At DATETIME NOT NULL, Estado TEXT NOT NULL DEFAULT 'PENDIENTE', Finalizada_At DATETIME, PRIMARY KEY (ID_Tarea, ID_Trabajador), FOREIGN KEY (ID_Tarea) REFERENCES Tareas(ID_Tarea) ON DELETE CASCADE, FOREIGN KEY (ID_Trabajador) REFERENCES Trabajadores(ID_Trabajador) ON DELETE CASCADE );
CREATE TABLE Tareas ( ID_Tarea TEXT NOT NULL PRIMARY KEY, Titulo TEXT NOT NULL, Descripcion TEXT, Fecha_Creacion DATETIME NOT NULL, Fecha_Limite DATE, Estado TEXT NOT NULL DEFAULT 'ABIERTA' );
CREATE TABLE Ticket_Settings ( ID INTEGER PRIMARY KEY CHECK (ID = 1), Show_Logo INTEGER NOT NULL DEFAULT 1, Show_BusinessName INTEGER NOT NULL DEFAULT 1, Show_Address INTEGER NOT NULL DEFAULT 1, Show_Phone INTEGER NOT NULL DEFAULT 1, Show_FooterMessage INTEGER NOT NULL DEFAULT 1, Paper_Width_Mm INTEGER NOT NULL DEFAULT 80, Paper_Dpi INTEGER NOT NULL DEFAULT 203, Chars_Per_Line INTEGER NOT NULL DEFAULT 42, Margin_Top_Mm REAL NOT NULL DEFAULT 0, Margin_Bottom_Mm REAL NOT NULL DEFAULT 0, Margin_Left_Mm REAL NOT NULL DEFAULT 0, Margin_Right_Mm REAL NOT NULL DEFAULT 0, Font_Scale REAL NOT NULL DEFAULT 1.0, Updated_At TEXT, CHECK (Paper_Width_Mm IN (58, 80, 112)), CHECK (Paper_Dpi IN (203, 300)), CHECK (Chars_Per_Line >= 20 AND Chars_Per_Line <= 80), CHECK (Font_Scale >= 0.5 AND Font_Scale <= 2.0) );
CREATE TABLE Trabajadores ( ID_Trabajador TEXT NOT NULL PRIMARY KEY, ID_Usuario TEXT UNIQUE NOT NULL, DNI TEXT UNIQUE, Telefono TEXT, Puesto TEXT, IBAN TEXT, Numero_Seguridad_Social TEXT UNIQUE, Fecha_Inicio_Contrato DATE, Fecha_Fin_Contrato DATE, FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) );
CREATE TABLE Turnos ( ID_Turno TEXT NOT NULL PRIMARY KEY, Nombre_Turno TEXT NOT NULL UNIQUE );
CREATE TABLE Usuarios ( ID_Usuario TEXT NOT NULL PRIMARY KEY, ID_Rol TEXT NOT NULL, Email TEXT NOT NULL UNIQUE, Password_Hash TEXT NOT NULL, Nombre TEXT NOT NULL, Apellido TEXT, Estado TEXT DEFAULT 'Activo', Requiere_Setup INTEGER DEFAULT 0, -- 1 = entra sin PIN: el login y el fichaje no se lo piden. Conserva su Password_Hash. Sin_PIN INTEGER NOT NULL DEFAULT 0 CHECK (Sin_PIN IN (0, 1)), FOREIGN KEY (ID_Rol) REFERENCES Roles(ID_Rol) );
CREATE TABLE Zonas ( ID_Zona TEXT NOT NULL PRIMARY KEY, Nombre_Zona TEXT NOT NULL, Room_Points TEXT NOT NULL DEFAULT '[]', Updated_At DATETIME, Archivada_En DATETIME );
CREATE TABLE _Backfill_Historico ( Tabla TEXT NOT NULL PRIMARY KEY, Orden INTEGER NOT NULL DEFAULT 0, Cursor INTEGER NOT NULL DEFAULT 0, Filas_Traidas INTEGER NOT NULL DEFAULT 0, Completada INTEGER NOT NULL DEFAULT 0, Ultimo_Intento_Ms INTEGER, Ultimo_Error TEXT, Ventana_Desde TEXT );
CREATE TABLE _Cobros_Pendientes ( ID_Pago TEXT PRIMARY KEY NOT NULL, Datos_Json TEXT NOT NULL CHECK (json_valid(Datos_Json)) );
CREATE TABLE _Estad_Dias_Sucios ( Dia TEXT NOT NULL PRIMARY KEY ) WITHOUT ROWID;
CREATE TABLE _Estad_Mesa_Dia ( Dia TEXT NOT NULL, ID_Mesa TEXT NOT NULL, Importe INTEGER NOT NULL CHECK (typeof(Importe) IN ('integer','null')), Comandas INTEGER NOT NULL, Comandas_Ultimo_Mes INTEGER NOT NULL, Comandas_Ultimo INTEGER NOT NULL, PRIMARY KEY (Dia, ID_Mesa) ) WITHOUT ROWID;
CREATE TABLE _Estad_Producto_Dia ( Dia TEXT NOT NULL, ID_Producto TEXT, Nombre_Producto TEXT, Milesimas INTEGER NOT NULL );
CREATE TABLE _Jobs_State ( Nombre TEXT NOT NULL PRIMARY KEY, Last_Run_Ms INTEGER, Last_Ok_Ms INTEGER, Last_Error TEXT, Fallos INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE _Negocio ( Id INTEGER PRIMARY KEY CHECK (Id = 1), ID_Negocio TEXT NOT NULL CHECK (length(ID_Negocio) > 0) );
CREATE TABLE _Recovery_State ( Id INTEGER PRIMARY KEY CHECK (Id = 1), Reconciliation_Pending INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE _Reservas_Web_Avisos ( ID_Aviso TEXT NOT NULL PRIMARY KEY, ID_Reserva TEXT NOT NULL, Tipo TEXT NOT NULL, Datos_Json TEXT NOT NULL CHECK (json_valid(Datos_Json)), Creado_Ms INTEGER NOT NULL, Intentos INTEGER NOT NULL DEFAULT 0, Ultimo_Error TEXT );
CREATE TABLE _Sync_Applied_Ops ( Op_Id TEXT NOT NULL PRIMARY KEY, Seq INTEGER NOT NULL, Applied_At_Ms INTEGER NOT NULL );
CREATE TABLE _Sync_Failed ( Op_Id TEXT NOT NULL PRIMARY KEY, Seq INTEGER NOT NULL, Statements_Json TEXT NOT NULL, Attempts INTEGER NOT NULL, Quarantined INTEGER NOT NULL DEFAULT 0, Last_Error TEXT, First_Failed_At_Ms INTEGER NOT NULL, Last_Failed_At_Ms INTEGER NOT NULL, Filas_Json TEXT CHECK (Filas_Json IS NULL OR json_valid(Filas_Json)), Datos_Vaciados_At_Ms INTEGER, Ultima_Salida_Ms INTEGER );
CREATE TABLE _Sync_Outbox ( Seq INTEGER PRIMARY KEY AUTOINCREMENT, Op_Id TEXT NOT NULL UNIQUE, Command_Name TEXT NOT NULL, Statements_Json TEXT NOT NULL, Created_At_Ms INTEGER NOT NULL, Intentos INTEGER NOT NULL DEFAULT 0, Ultimo_Error TEXT, Ultimo_Intento_Ms INTEGER, Cuarentena INTEGER NOT NULL DEFAULT 0, -- SYNC-26: si esta fila es una REPARACION, el Op_Id de la operacion apartada que la motivo. -- -- Existe para poder cerrar el aviso. Sin el enlace, una operacion apartada se quedaba en -- cuarentena para siempre aunque su reparacion hubiera subido: el panel seguiria diciendo -- "hay cambios que la nube ha rechazado" con el problema ya resuelto, y un aviso que no se -- apaga solo cuando el problema se arregla ensena a descartar avisos. Repara_Op_Id TEXT );
CREATE TABLE _Sync_State ( Id INTEGER PRIMARY KEY CHECK (Id = 1), Last_Seq INTEGER NOT NULL );
CREATE TABLE _Verifactu_Anomalias ( ID_Anomalia TEXT NOT NULL PRIMARY KEY, Clase TEXT NOT NULL, Mensaje TEXT NOT NULL, ID_Registro TEXT, Detectada_En_Ms INTEGER NOT NULL, Reconocida INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE _Verifactu_Envios ( ID_Registro TEXT NOT NULL PRIMARY KEY, Estado TEXT NOT NULL, Intentos INTEGER NOT NULL DEFAULT 0, Ultimo_Intento_Ms INTEGER, Codigo_Error TEXT, Descripcion_Error TEXT, CSV TEXT, Creado_En_Ms INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE _Verifactu_Flujo ( ID INTEGER PRIMARY KEY CHECK (ID = 1), Espera_Segundos INTEGER NOT NULL DEFAULT 60, Ultimo_Envio_Ms INTEGER );
CREATE TABLE _Verificacion_Nube ( Id INTEGER PRIMARY KEY CHECK (Id = 1), Ultima_Ok_Ms INTEGER, Ultimo_Intento_Ms INTEGER, Fallos INTEGER NOT NULL DEFAULT 0 );
CREATE TRIGGER asig_validar_insert BEFORE INSERT ON Asignacion_Turnos BEGIN SELECT RAISE(ABORT, 'horario_invalido') WHERE date(NEW.Fecha) IS NULL OR date(NEW.Fecha) <> NEW.Fecha OR (NEW.Hora_Inicio IS NULL) <> (NEW.Hora_Fin IS NULL) OR (NEW.Hora_Inicio IS NOT NULL AND (time(NEW.Hora_Inicio) IS NULL OR time(NEW.Hora_Fin) IS NULL OR time(NEW.Hora_Inicio) = time(NEW.Hora_Fin))); SELECT RAISE(ABORT, 'horario_solapado') WHERE NEW.Hora_Inicio IS NOT NULL AND EXISTS ( SELECT 1 FROM Asignacion_Turnos a WHERE a.ID_Trabajador = NEW.ID_Trabajador AND a.ID_Asignacion <> NEW.ID_Asignacion AND a.Hora_Inicio IS NOT NULL AND datetime(a.Fecha || ' ' || a.Hora_Inicio) < datetime(NEW.Fecha || ' ' || NEW.Hora_Fin, CASE WHEN time(NEW.Hora_Fin) < time(NEW.Hora_Inicio) THEN '+1 day' ELSE '+0 day' END) AND datetime(NEW.Fecha || ' ' || NEW.Hora_Inicio) < datetime(a.Fecha || ' ' || a.Hora_Fin, CASE WHEN time(a.Hora_Fin) < time(a.Hora_Inicio) THEN '+1 day' ELSE '+0 day' END) ); END;
CREATE TRIGGER asig_validar_update BEFORE UPDATE ON Asignacion_Turnos BEGIN SELECT RAISE(ABORT, 'horario_invalido') WHERE date(NEW.Fecha) IS NULL OR date(NEW.Fecha) <> NEW.Fecha OR (NEW.Hora_Inicio IS NULL) <> (NEW.Hora_Fin IS NULL) OR (NEW.Hora_Inicio IS NOT NULL AND (time(NEW.Hora_Inicio) IS NULL OR time(NEW.Hora_Fin) IS NULL OR time(NEW.Hora_Inicio) = time(NEW.Hora_Fin))); SELECT RAISE(ABORT, 'horario_solapado') WHERE NEW.Hora_Inicio IS NOT NULL AND EXISTS ( SELECT 1 FROM Asignacion_Turnos a WHERE a.ID_Trabajador = NEW.ID_Trabajador AND a.ID_Asignacion <> NEW.ID_Asignacion AND a.Hora_Inicio IS NOT NULL AND datetime(a.Fecha || ' ' || a.Hora_Inicio) < datetime(NEW.Fecha || ' ' || NEW.Hora_Fin, CASE WHEN time(NEW.Hora_Fin) < time(NEW.Hora_Inicio) THEN '+1 day' ELSE '+0 day' END) AND datetime(NEW.Fecha || ' ' || NEW.Hora_Inicio) < datetime(a.Fecha || ' ' || a.Hora_Fin, CASE WHEN time(a.Hora_Fin) < time(a.Hora_Inicio) THEN '+1 day' ELSE '+0 day' END) ); END;
CREATE TRIGGER estad_comandas_delete AFTER DELETE ON Comandas BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pagos p WHERE p.ID_Comanda = OLD.ID_Comanda AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_comandas_insert AFTER INSERT ON Comandas BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pagos p WHERE p.ID_Comanda = NEW.ID_Comanda AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_comandas_update AFTER UPDATE OF ID_Comanda, ID_Mesa ON Comandas WHEN OLD.ID_Comanda IS NOT NEW.ID_Comanda OR OLD.ID_Mesa IS NOT NEW.ID_Mesa BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pagos p WHERE p.ID_Comanda IN (OLD.ID_Comanda, NEW.ID_Comanda) AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_detalle_comanda_delete AFTER DELETE ON Detalle_Comanda BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pago_Detalles pd JOIN Pagos p ON p.ID_Pago = pd.ID_Pago WHERE pd.ID_Detalle = OLD.ID_Detalle AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_detalle_comanda_insert AFTER INSERT ON Detalle_Comanda BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pago_Detalles pd JOIN Pagos p ON p.ID_Pago = pd.ID_Pago WHERE pd.ID_Detalle = NEW.ID_Detalle AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_detalle_comanda_update AFTER UPDATE OF ID_Detalle, ID_Producto, Nombre_Producto, Cantidad ON Detalle_Comanda WHEN OLD.ID_Detalle IS NOT NEW.ID_Detalle OR OLD.ID_Producto IS NOT NEW.ID_Producto OR OLD.Nombre_Producto IS NOT NEW.Nombre_Producto OR OLD.Cantidad IS NOT NEW.Cantidad BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pago_Detalles pd JOIN Pagos p ON p.ID_Pago = pd.ID_Pago WHERE pd.ID_Detalle IN (OLD.ID_Detalle, NEW.ID_Detalle) AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_pago_detalles_delete AFTER DELETE ON Pago_Detalles BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT substr(p.Fecha_Hora, 1, 10) FROM Pagos p WHERE p.ID_Pago = OLD.ID_Pago AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pago_Detalles otro JOIN Pagos p ON p.ID_Pago = otro.ID_Pago WHERE otro.ID_Detalle = OLD.ID_Detalle AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_pago_detalles_insert AFTER INSERT ON Pago_Detalles BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pago_Detalles otro JOIN Pagos p ON p.ID_Pago = otro.ID_Pago WHERE otro.ID_Detalle = NEW.ID_Detalle AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_pago_detalles_update AFTER UPDATE OF ID_Pago, ID_Detalle ON Pago_Detalles WHEN OLD.ID_Pago IS NOT NEW.ID_Pago OR OLD.ID_Detalle IS NOT NEW.ID_Detalle BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT substr(p.Fecha_Hora, 1, 10) FROM Pagos p WHERE p.ID_Pago = OLD.ID_Pago AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pago_Detalles otro JOIN Pagos p ON p.ID_Pago = otro.ID_Pago WHERE otro.ID_Detalle IN (OLD.ID_Detalle, NEW.ID_Detalle) AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_pagos_delete AFTER DELETE ON Pagos BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT substr(OLD.Fecha_Hora, 1, 10) WHERE substr(OLD.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pagos p WHERE p.ID_Comanda = OLD.ID_Comanda AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pago_Detalles pd JOIN Pago_Detalles otro ON otro.ID_Detalle = pd.ID_Detalle JOIN Pagos p ON p.ID_Pago = otro.ID_Pago WHERE pd.ID_Pago = OLD.ID_Pago AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_pagos_insert AFTER INSERT ON Pagos BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pagos p WHERE p.ID_Comanda = NEW.ID_Comanda AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pago_Detalles pd JOIN Pago_Detalles otro ON otro.ID_Detalle = pd.ID_Detalle JOIN Pagos p ON p.ID_Pago = otro.ID_Pago WHERE pd.ID_Pago = NEW.ID_Pago AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_pagos_reemplazo BEFORE INSERT ON Pagos BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pagos viejo JOIN Pagos p ON p.ID_Comanda = viejo.ID_Comanda WHERE viejo.ID_Pago = NEW.ID_Pago AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_pagos_reemplazo_clave BEFORE UPDATE OF ID_Pago ON Pagos WHEN OLD.ID_Pago IS NOT NEW.ID_Pago BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pagos desplazado JOIN Pagos p ON p.ID_Comanda = desplazado.ID_Comanda WHERE desplazado.ID_Pago = NEW.ID_Pago AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER estad_pagos_update AFTER UPDATE OF ID_Pago, ID_Comanda, Fecha_Hora, Importe_Total, Estado, ID_Pago_Origen ON Pagos WHEN OLD.ID_Pago IS NOT NEW.ID_Pago OR OLD.ID_Comanda IS NOT NEW.ID_Comanda OR OLD.Fecha_Hora IS NOT NEW.Fecha_Hora OR OLD.Importe_Total IS NOT NEW.Importe_Total OR OLD.Estado IS NOT NEW.Estado OR OLD.ID_Pago_Origen IS NOT NEW.ID_Pago_Origen BEGIN INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT substr(OLD.Fecha_Hora, 1, 10) WHERE substr(OLD.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pagos p WHERE p.ID_Comanda IN (OLD.ID_Comanda, NEW.ID_Comanda) AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); INSERT OR IGNORE INTO _Estad_Dias_Sucios (Dia) SELECT DISTINCT substr(p.Fecha_Hora, 1, 10) FROM Pago_Detalles pd JOIN Pago_Detalles otro ON otro.ID_Detalle = pd.ID_Detalle JOIN Pagos p ON p.ID_Pago = otro.ID_Pago WHERE pd.ID_Pago IN (OLD.ID_Pago, NEW.ID_Pago) AND substr(p.Fecha_Hora, 1, 10) NOT IN (SELECT Dia FROM _Estad_Dias_Sucios); END;
CREATE TRIGGER ri48_detalle_comanda_estado_cocina_insert BEFORE INSERT ON Detalle_Comanda WHEN NOT (NEW.Estado_Cocina IS NULL OR NEW.Estado_Cocina IN ('PENDIENTE','PREPARADO')) BEGIN SELECT RAISE(ABORT, 'RI48: Detalle_Comanda.Estado_Cocina no admitido'); END;
CREATE TRIGGER ri48_detalle_comanda_estado_cocina_update BEFORE UPDATE ON Detalle_Comanda WHEN NOT (NEW.Estado_Cocina IS NULL OR NEW.Estado_Cocina IN ('PENDIENTE','PREPARADO')) BEGIN SELECT RAISE(ABORT, 'RI48: Detalle_Comanda.Estado_Cocina no admitido'); END;
CREATE TRIGGER ri48_fichajes_estado_insert BEFORE INSERT ON Fichajes WHEN NOT (NEW.Estado IS NULL OR NEW.Estado IN ('ABIERTO','CERRADO')) BEGIN SELECT RAISE(ABORT, 'RI48: Fichajes.Estado no admitido'); END;
CREATE TRIGGER ri48_fichajes_estado_update BEFORE UPDATE ON Fichajes WHEN NOT (NEW.Estado IS NULL OR NEW.Estado IN ('ABIERTO','CERRADO')) BEGIN SELECT RAISE(ABORT, 'RI48: Fichajes.Estado no admitido'); END;
CREATE TRIGGER ri48_movimientos_caja_metodo_pago_insert BEFORE INSERT ON Movimientos_Caja WHEN NOT (NEW.Metodo_Pago IS NULL OR NEW.Metodo_Pago IN ('Efectivo','Tarjeta','Otro')) BEGIN SELECT RAISE(ABORT, 'RI48: Movimientos_Caja.Metodo_Pago no admitido'); END;
CREATE TRIGGER ri48_movimientos_caja_metodo_pago_update BEFORE UPDATE ON Movimientos_Caja WHEN NOT (NEW.Metodo_Pago IS NULL OR NEW.Metodo_Pago IN ('Efectivo','Tarjeta','Otro')) BEGIN SELECT RAISE(ABORT, 'RI48: Movimientos_Caja.Metodo_Pago no admitido'); END;
CREATE TRIGGER ri48_pagos_metodo_pago_insert BEFORE INSERT ON Pagos WHEN NOT (NEW.Metodo_Pago IN ('Efectivo','Tarjeta') OR (NEW.Metodo_Pago = 'Otro' AND NEW.Tipo = 'DEVOLUCION')) BEGIN SELECT RAISE(ABORT, 'RI48: Pagos.Metodo_Pago no admitido'); END;
CREATE TRIGGER ri48_pagos_metodo_pago_update BEFORE UPDATE ON Pagos WHEN NOT (NEW.Metodo_Pago IN ('Efectivo','Tarjeta') OR (NEW.Metodo_Pago = 'Otro' AND NEW.Tipo = 'DEVOLUCION')) BEGIN SELECT RAISE(ABORT, 'RI48: Pagos.Metodo_Pago no admitido'); END;
CREATE TRIGGER ri48_reservas_estado_insert BEFORE INSERT ON Reservas WHEN NOT (NEW.Estado IN ('PROXIMA','ACTIVA','FINALIZADA','CANCELADA','NO_SHOW')) BEGIN SELECT RAISE(ABORT, 'RI48: Reservas.Estado no admitido'); END;
CREATE TRIGGER ri48_reservas_estado_update BEFORE UPDATE ON Reservas WHEN NOT (NEW.Estado IN ('PROXIMA','ACTIVA','FINALIZADA','CANCELADA','NO_SHOW')) BEGIN SELECT RAISE(ABORT, 'RI48: Reservas.Estado no admitido'); END;
CREATE TRIGGER ri48_reservas_origen_insert BEFORE INSERT ON Reservas WHEN NOT (NEW.Origen IN ('TPV','WEB')) BEGIN SELECT RAISE(ABORT, 'RI48: Reservas.Origen no admitido'); END;
CREATE TRIGGER ri48_reservas_origen_update BEFORE UPDATE ON Reservas WHEN NOT (NEW.Origen IN ('TPV','WEB')) BEGIN SELECT RAISE(ABORT, 'RI48: Reservas.Origen no admitido'); END;
CREATE TRIGGER ri48_tarea_asignaciones_estado_insert BEFORE INSERT ON Tarea_Asignaciones WHEN NOT (NEW.Estado IN ('PENDIENTE','FINALIZADA')) BEGIN SELECT RAISE(ABORT, 'RI48: Tarea_Asignaciones.Estado no admitido'); END;
CREATE TRIGGER ri48_tarea_asignaciones_estado_update BEFORE UPDATE ON Tarea_Asignaciones WHEN NOT (NEW.Estado IN ('PENDIENTE','FINALIZADA')) BEGIN SELECT RAISE(ABORT, 'RI48: Tarea_Asignaciones.Estado no admitido'); END;
CREATE TRIGGER ri48_tareas_estado_insert BEFORE INSERT ON Tareas WHEN NOT (NEW.Estado IN ('ABIERTA','ELIMINADA')) BEGIN SELECT RAISE(ABORT, 'RI48: Tareas.Estado no admitido'); END;
CREATE TRIGGER ri48_tareas_estado_update BEFORE UPDATE ON Tareas WHEN NOT (NEW.Estado IN ('ABIERTA','ELIMINADA')) BEGIN SELECT RAISE(ABORT, 'RI48: Tareas.Estado no admitido'); END;
CREATE VIEW v_inventario_producto_stock AS WITH agg AS ( SELECT ID_Producto, COALESCE(SUM(Stock_Disponible), 0) AS Stock_Actual, MIN(CASE WHEN COALESCE(Stock_Disponible, 0) > 0 THEN Caducidad END) AS Caducidad_Proxima FROM Lotes_Producto GROUP BY ID_Producto ), lote_fefo AS ( SELECT ID_Producto, Codigo_Lote FROM ( SELECT ID_Producto, Codigo_Lote, ROW_NUMBER() OVER ( PARTITION BY ID_Producto ORDER BY CASE WHEN Caducidad IS NULL THEN 1 ELSE 0 END, date(Caducidad) ASC, datetime(Fecha_Entrada) ASC, ID_Lote ASC ) AS rn FROM Lotes_Producto WHERE COALESCE(Stock_Disponible, 0) > 0 ) WHERE rn = 1 ) SELECT p.ID_Producto, COALESCE(a.Stock_Actual, 0) AS Stock_Actual, a.Caducidad_Proxima AS Caducidad_Proxima, f.Codigo_Lote AS Lote_Proximo FROM Productos p LEFT JOIN agg a ON a.ID_Producto = p.ID_Producto LEFT JOIN lote_fefo f ON f.ID_Producto = p.ID_Producto;
CREATE VIEW v_lineas_cobradas AS SELECT pd.ID_Pago AS ID_Pago, pd.ID_Detalle AS ID_Detalle FROM Pago_Detalles pd JOIN Pagos p ON p.ID_Pago = pd.ID_Pago WHERE +p.Estado = 'ACTIVO';
CREATE VIEW v_unidades_devueltas AS SELECT d.ID_Pago_Origen AS ID_Pago, dl.ID_Detalle AS ID_Detalle, SUM(dl.Cantidad) AS Cantidad, SUM(dl.Importe) AS Importe FROM Devolucion_Lineas dl JOIN Pagos d ON d.ID_Pago = dl.ID_Pago WHERE +d.Estado = 'ACTIVO' GROUP BY d.ID_Pago_Origen, dl.ID_Detalle;
